# a long formula after some text goes to its own line, so a line never stretches around it
def _w(s):
    s=re.sub(r'\\[dt]?frac\{([^{}]*)\}\{([^{}]*)\}',lambda m:max(m.group(1),m.group(2),key=len),s)
    s=re.sub(r'\\(left|right|quad|qquad|limits|displaystyle|mathbb|RR|textbf|ck)','',s)
    s=re.sub(r'\\[a-zA-Z]+','x',s)
    return len(re.sub(r'[{}$^_ ]','',s))
def brk(x):
    parts=re.split(r'(\$[^$]+\$)',x); out=''; acc=0
    for q in parts:
        if q.startswith('$') and _w(q)>=14 and acc>=4 and acc+_w(q)>46 and not out.rstrip().endswith(r'\par'):
            out+=r'\par '
            acc=0
        out+=q; acc+=_w(q)
    return out
_Q=Q
Q=lambda *xs:_Q(*[brk(x) for x in xs])
_QN=QN
QN=lambda n,x:_QN(n,brk(x))
LN=r'\lim\limits_{n\to+\infty}'
