S.append(sess('32',r'خواص المتتاليات: المحدودة والرتيبة',
[r'الاستدلال بالتراجع ، المشتقات.'],
[r'إثبات أن متتالية محدودة ، ودراسة اتجاه تغيرها.'],TOOLS,
r'$v_n=\dfrac{2n+1}{n+1}$: هل يمكن أن يتجاوز $v_n$ العدد $2$ ؟',
ACT('04')+r'\ $v_n=\dfrac{2n+1}{n+1}$ ($n\in\mathbb N$).'+Q(r'بيّن أن $v_n=2-\dfrac1{n+1}$.',r'استنتج أن $1\leqslant v_n<2$.',r'ادرس اتجاه تغير $(v_n)$.')
+DIS()+Q(r'$2-\dfrac1{n+1}=\dfrac{2n+2-1}{n+1}=\RR{\dfrac{2n+1}{n+1}}$.',r'$0<\dfrac1{n+1}\leqslant1\ \Rightarrow\ -1\leqslant-\dfrac1{n+1}<0\ \Rightarrow\ \RR{1\leqslant v_n<2}$.',
 r'$v_{n+1}-v_n=\dfrac1{n+1}-\dfrac1{n+2}=\RR{\dfrac1{(n+1)(n+2)}>0}$: \RR{متزايدة تمامًا}.'),
DEF('متتالية محدودة')+Q(r'$(u_n)$ \textbf{محدودة من الأعلى} إذا وُجد $M$ حيث $u_n\leqslant M$ لكل $n$.',r'\textbf{محدودة من الأسفل} إذا وُجد $m$ حيث $u_n\geqslant m$ لكل $n$.',r'\textbf{محدودة} إذا كانت محدودة من الأعلى ومن الأسفل: $\RR{m\leqslant u_n\leqslant M}$.')
+DEF('متتالية رتيبة')+r'\ متزايدة ($u_{n+1}\geqslant u_n$) أو متناقصة ($u_{n+1}\leqslant u_n$) من أجل كل $n$ ، أو ابتداءً من رتبة معينة.'
+MET('دراسة اتجاه التغير')+Q(r'إشارة الفرق $u_{n+1}-u_n$.',r'مقارنة $\dfrac{u_{n+1}}{u_n}$ بالعدد $1$ (حدود موجبة تمامًا).',r'اتجاه تغير $f$ إذا كان $u_n=f(n)$.',r'التراجع إذا كانت $u_{n+1}=f(u_n)$.')
+EX('أمثلة محلولة')+Q(r'\textbf{الفرق:} $u_n=n^2-4n$: $u_{n+1}-u_n=(n+1)^2-4(n+1)-n^2+4n=\RR{2n-3}$ ، موجب من أجل $n\geqslant2$: \RR{متزايدة ابتداءً من الرتبة 2}.',
 r'\textbf{النسبة:} $w_n=\dfrac{n}{3^n}$ ($n\geqslant1$): $\dfrac{w_{n+1}}{w_n}=\dfrac{n+1}{3^{n+1}}\times\dfrac{3^n}{n}=\RR{\dfrac{n+1}{3n}}\leqslant1$ لأن $n+1\leqslant3n$: \RR{متناقصة}.',
 r'\textbf{الدالة:} $u_n=f(n)$ مع $f(x)=\dfrac{x}{x+1}$: $f^{\prime}(x)=\dfrac1{(x+1)^2}>0$: \RR{متزايدة}.',
 r'\textbf{التراجع:} $u_0=0$ ، $u_{n+1}=\sqrt{u_n+2}$: $P(n)$: $u_n\leqslant u_{n+1}$.',
 r'التحقق: $u_0=0\leqslant\sqrt2=u_1$ \ck',r'الوراثة: $u_n\leqslant u_{n+1}\ \Rightarrow\ \sqrt{u_n+2}\leqslant\sqrt{u_{n+1}+2}\ \Rightarrow\ \RR{u_{n+1}\leqslant u_{n+2}}$.')
+WARN()+r'\ $(-1)^n$ محدودة ($-1\leqslant(-1)^n\leqslant1$) وليست رتيبة.',
TT()+r'\par $w_n=\dfrac{n}{n^2+1}$ ($n\in\mathbb N$).'+Q(r'بيّن أن $0\leqslant w_n\leqslant\dfrac12$.',r'ادرس اتجاه تغير $(w_n)$ ابتداءً من الرتبة $1$.')
+SOL()+Q(r'$w_n\geqslant0$ ؛ \quad $\dfrac12-w_n=\dfrac{n^2+1-2n}{2(n^2+1)}=\RR{\dfrac{(n-1)^2}{2(n^2+1)}\geqslant0}$.',
 r'$w_{n+1}-w_n=\dfrac{(n+1)(n^2+1)-n\left((n+1)^2+1\right)}{\left((n+1)^2+1\right)(n^2+1)}=\RR{\dfrac{-n^2-n+1}{\left((n+1)^2+1\right)(n^2+1)}}$.',
 r'من أجل $n\geqslant1$: $-n^2-n+1\leqslant-1<0$ ، إذن \RR{$(w_n)$ متناقصة}.')
+HW(r'تمارين من باب المتتاليات (محدودة ، رتيبة).'),
[r'سؤال تمهيدي.',r'كتابة جديدة للعبارة.',r'جدول الطرق.',r'تقويم فردي.']))
# ---------------------------------------------------------------- 33
S.append(sess('33',r'خواص المتتاليات: التقارب والنهاية',
[r'المتتاليات المحدودة والرتيبة ، النهايات ، الاستمرارية.'],
[r'إثبات تقارب متتالية وحساب نهايتها.'],TOOLS,
r'متتالية متزايدة ولا تتجاوز $2$: هل يمكن أن تؤول إلى $+\infty$ ؟',
ACT('05')+r'\ $u_0=0$ ، $u_{n+1}=\sqrt{u_n+2}$. (أثبتنا: $0\leqslant u_n\leqslant2$ و $(u_n)$ متزايدة.)'+Q(r'هل يمكن أن تكون $'+LN+r'u_n=+\infty$ ؟',r'نفرض $'+LN+r'u_n=\ell$: ما المعادلة التي يحققها $\ell$ ؟ حلها.')
+DIS()+Q(r'لا ، لأن $u_n\leqslant2$: الحدود تتزايد و«تتراكم» تحت $2$: \RR{متقاربة}.',r'بالمرور إلى النهاية في $u_{n+1}=\sqrt{u_n+2}$: $\ell=\sqrt{\ell+2}\ \Rightarrow\ \ell^2-\ell-2=0\ \Rightarrow\ \RR{\ell=2}$ ($\ell=-1$ مرفوض).'),
DEF()+r'\ $(u_n)$ \textbf{متقاربة} إذا كانت لها نهاية حقيقية $\ell$ ، وإلا فهي \textbf{متباعدة}. إذا كان $u_n=f(n)$ و $\lim\limits_{x\to+\infty}f(x)=\ell$ فإن $\RR{'+LN+r'u_n=\ell}$.'
+PRO('نهاية $q^n$')+Q(r'$q>1$: $'+LN+r'q^n=+\infty$ ؛ \quad $q=1$: $'+LN+r'q^n=1$.',r'$-1<q<1$: $\RR{'+LN+r'q^n=0}$ ؛ \quad $q\leqslant-1$: ليس لها نهاية.')
+PRO('المقارنة والحصر')+Q(r'$u_n\geqslant v_n$ و $'+LN+r'v_n=+\infty$ $\Rightarrow$ $'+LN+r'u_n=+\infty$.',r'$v_n\leqslant u_n\leqslant w_n$ و $'+LN+r'v_n='+LN+r'w_n=\ell$ $\Rightarrow$ $\RR{'+LN+r'u_n=\ell}$.')
+PRO('التقارب الرتيب')+Q(r'كل متتالية \textbf{متزايدة ومحدودة من الأعلى} متقاربة ؛ كل متتالية \textbf{متناقصة ومحدودة من الأسفل} متقاربة.',r'إذا كانت $u_{n+1}=f(u_n)$ متقاربة نحو $\ell$ و $f$ مستمرة عند $\ell$ فإن $\RR{f(\ell)=\ell}$.')
+EX('أمثلة محلولة')+Q(r'$'+LN+r'\dfrac{2^n-3^n}{3^n+1}='+LN+r'\dfrac{\left(\frac23\right)^n-1}{1+\left(\frac13\right)^n}=\RR{-1}$.',
 r'$-\dfrac1n\leqslant\dfrac{\cos n}{n}\leqslant\dfrac1n$ والطرفان يؤولان إلى $0$: $\RR{'+LN+r'\dfrac{\cos n}{n}=0}$.',
 r'$'+LN+r'\left(5-3\times0{,}8^n\right)=\RR{5}$ لأن $0<0{,}8<1$.',
 r'$(u_n)$ النشاط: متزايدة ومحدودة من الأعلى بـ $2$ إذن متقاربة.',r'$f(x)=\sqrt{x+2}$ مستمرة ، إذن $\RR{'+LN+r'u_n=2}$.')
+WARN()+r'\ لا نستعمل $f(\ell)=\ell$ قبل إثبات التقارب.\par المبرهنة لا تعطي قيمة النهاية: $2-\dfrac1{n+1}\leqslant5$ لكن النهاية $2$.',
TT()+r'\par احسب النهايات:'+Q(r'$w_n=\dfrac{3n^2+1}{n^2+n}$.',r'$t_n=\dfrac{(-1)^n}{n+1}$.',r'$s_n=n+(-1)^n$.')
+SOL()+Q(r'$w_n=\dfrac{3+\frac1{n^2}}{1+\frac1n}$ ، إذن $\RR{'+LN+r'w_n=3}$.',r'$|t_n|=\dfrac1{n+1}$ و $-\dfrac1{n+1}\leqslant t_n\leqslant\dfrac1{n+1}$ ، إذن $\RR{'+LN+r't_n=0}$.',r'$s_n\geqslant n-1$ و $'+LN+r'(n-1)=+\infty$ ، إذن $\RR{'+LN+r's_n=+\infty}$.')
+HW(r'تمرينا 28 و 29 ، و 123 و 124 صفحة 25.'),
[r'تخمين.',r'برهان كامل.',r'خطوات التحرير.',r'تقويم فردي.']))
# ---------------------------------------------------------------- 34
S.append(sess('34',r'المتتاليتان المتجاورتان',
[r'التقارب ، الرتابة ، المتتاليات الهندسية.'],
[r'إثبات أن متتاليتين متجاورتان واستنتاج نهايتهما المشتركة.'],TOOLS,
r'كيف نحصر عددًا مجهولًا بين قيم مقربة بالنقصان وأخرى بالزيادة تتقارب؟',
ACT('06')+r'\ من أجل $n\geqslant1$: $u_n=2-\dfrac1n$ و $v_n=2+\dfrac1{n^2}$.'+Q(r'احسب $u_1$ ، $u_2$ ، $v_1$ ، $v_2$.',r'ادرس اتجاه تغير كل منهما.',r'احسب $'+LN+r'(v_n-u_n)$.')
+DIS()+Q(r'$u_1=\RR{1}$ ، $u_2=\RR{1{,}5}$ ؛ $v_1=\RR{3}$ ، $v_2=\RR{2{,}25}$.',
 r'$u_{n+1}-u_n=\dfrac1n-\dfrac1{n+1}=\RR{\dfrac1{n(n+1)}>0}$: $(u_n)$ \RR{متزايدة}.',
 r'$v_{n+1}-v_n=\dfrac1{(n+1)^2}-\dfrac1{n^2}<0$: $(v_n)$ \RR{متناقصة}.',
 r'$v_n-u_n=\dfrac1{n^2}+\dfrac1n$ ، إذن $\RR{'+LN+r'(v_n-u_n)=0}$: المتتاليتان تحصران العدد $2$.'),
DEF()+r'\ $(u_n)$ و $(v_n)$ \textbf{متجاورتان} إذا كانت إحداهما متزايدة والأخرى متناقصة و $\RR{'+LN+r'(v_n-u_n)=0}$.'
+PRO()+r'\ إذا كانت $(u_n)$ متزايدة و $(v_n)$ متناقصة ومتجاورتين ، فإنهما \textbf{متقاربتان نحو نفس النهاية} $\ell$ ، و $\RR{u_n\leqslant\ell\leqslant v_n}$ لكل $n$.'
+EX('مثال محلول')+r'\ $u_0=1$ ، $v_0=8$ ، $u_{n+1}=\dfrac{2u_n+v_n}3$ ، $v_{n+1}=\dfrac{u_n+3v_n}4$ ، $w_n=v_n-u_n$ ، $t_n=3u_n+4v_n$.'
+Q(r'$w_{n+1}=\dfrac{u_n+3v_n}4-\dfrac{2u_n+v_n}3=\dfrac{3u_n+9v_n-8u_n-4v_n}{12}=\RR{\dfrac5{12}w_n}$.',
 r'$(w_n)$ هندسية ، $w_0=7$: $w_n=\RR{7\left(\dfrac5{12}\right)^n}>0$ و $\RR{'+LN+r'w_n=0}$.',
 r'$u_{n+1}-u_n=\dfrac{v_n-u_n}3=\dfrac{w_n}3>0$: \RR{$(u_n)$ متزايدة}.',
 r'$v_{n+1}-v_n=\dfrac{u_n-v_n}4=-\dfrac{w_n}4<0$: \RR{$(v_n)$ متناقصة} ، إذن \RR{متجاورتان}.',
 r'$t_{n+1}=(2u_n+v_n)+(u_n+3v_n)=3u_n+4v_n=t_n$: ثابتة ، $t_n=t_0=3+32=\RR{35}$.',
 r'بالمرور إلى النهاية: $3\ell+4\ell=35\ \Rightarrow\ \RR{\ell=5}$.')
+WARN()+r'\ نتحقق من الشروط الثلاثة كلها (تزايد ، تناقص ، نهاية الفرق).',
TT()+r'\par $u_n=1-\dfrac1{2^n}$ و $v_n=1+\dfrac1n$ ($n\geqslant1$).'+Q(r'بيّن أن $(u_n)$ و $(v_n)$ متجاورتان.',r'عيّن نهايتهما المشتركة.')
+SOL()+Q(r'$u_{n+1}-u_n=\dfrac1{2^n}-\dfrac1{2^{n+1}}=\RR{\dfrac1{2^{n+1}}>0}$: متزايدة.',r'$v_{n+1}-v_n=\dfrac1{n+1}-\dfrac1n=\RR{-\dfrac1{n(n+1)}<0}$: متناقصة.',
 r'$v_n-u_n=\dfrac1n+\dfrac1{2^n}\to0$: \RR{متجاورتان}.',r'$'+LN+r'u_n=1-0=\RR{1}$: النهاية المشتركة $1$.')
+HW(r'تمرين 135 صفحة 37.'),
[r'سؤال حصر.',r'مناقشة النشاط.',r'الشروط الثلاثة.',r'تقويم فردي.']))
# ---------------------------------------------------------------- 35
S.append(sess('35',r'حل مشكلات توظف المتتاليات والبرهان بالتراجع',
[r'المتتالية المساعدة ، التقارب ، الاستدلال بالتراجع ، الدالة اللوغاريتمية.'],
[r'نمذجة وضعية بمتتالية وحل المشكلة وتفسير النتائج.'],TOOLS,
r'غابة فيها $1000$ شجرة ، يُقطع $10\,\%$ منها كل سنة ويُغرس $200$ شجرة: كم شجرة على المدى البعيد؟',
ACT('07')+r'\ $P_n$ عدد الأشجار بعد $n$ سنة: $P_0=1000$.'+Q(r'بيّن أن $P_{n+1}=0{,}9P_n+200$.',r'برهن بالتراجع أن $P_n\leqslant2000$ ، ثم أن $(P_n)$ متزايدة.',r'نضع $v_n=P_n-2000$: بيّن أن $(v_n)$ هندسية ، واكتب $P_n$ بدلالة $n$.',r'احسب $'+LN+r'P_n$ وفسّر. ابتداءً من أي سنة يتجاوز العدد $1900$ ؟')
+DIS()+Q(r'يبقى $90\,\%$ أي $0{,}9P_n$ ونضيف $200$: $\RR{P_{n+1}=0{,}9P_n+200}$.',
 r'التحقق: $P_0=1000\leqslant2000$ \ck ؛ الوراثة: $P_{n+1}=0{,}9P_n+200\leqslant0{,}9\times2000+200=\RR{2000}$.',
 r'$P_{n+1}-P_n=200-0{,}1P_n=0{,}1(2000-P_n)\geqslant0$: \RR{متزايدة}.',
 r'$v_{n+1}=0{,}9P_n+200-2000=0{,}9(P_n-2000)=\RR{0{,}9\,v_n}$ ؛ $v_0=\RR{-1000}$.',
 r'$v_n=-1000\times0{,}9^n$ ؛ \quad $P_n=\RR{2000-1000\times0{,}9^n}$.',
 r'$0<0{,}9<1$: $\RR{'+LN+r'P_n=2000}$: يستقر العدد قرب $2000$ شجرة.',
 r'$P_n>1900\iff0{,}9^n<0{,}1\iff n>\dfrac{\ln0{,}1}{\ln0{,}9}\approx21{,}85$: ابتداءً من \RR{السنة 22}.'),
MET('حل مشكلة بمتتالية')+Q(r'ترييض الوضعية: $u_0$ وعلاقة $u_{n+1}=f(u_n)$.',r'متتالية مساعدة (غالبًا هندسية) ثم عبارة الحد العام.',r'الرتابة ، الحصر (بالتراجع) ، النهاية.',r'تفسير النتائج بلغة الوضعية.')
+EX('مثال محلول: إيداع')+r'\ نودع $100000$ دج بفائدة مركبة $4\,\%$ سنويًا: $C_{n+1}=1{,}04\,C_n$.'
+Q(r'$(C_n)$ هندسية أساسها $1{,}04$: $C_n=\RR{100000\times1{,}04^n}$.',r'$C_{10}=100000\times1{,}04^{10}\approx\RR{148024{,}43}$ دج.',
 r'$C_n\geqslant200000\iff1{,}04^n\geqslant2\iff n\geqslant\dfrac{\ln2}{\ln1{,}04}\approx17{,}67$: يتضاعف المبلغ ابتداءً من \RR{السنة 18}.')
+WARN()+r'\ نفسر النتيجة بلغة الوضعية (عدد الأشجار ، المبلغ) ، ونقرّب عدد السنوات إلى العدد الطبيعي الموالي.',
TT()+r'\par مريض يأخذ $2$ mg من دواء يوميًا ، ويطرح جسمه نصف الكمية يوميًا: $d_0=2$ ، $d_{n+1}=0{,}5d_n+2$.'+Q(r'نضع $v_n=d_n-4$: بيّن أن $(v_n)$ هندسية.',r'اكتب $d_n$ بدلالة $n$ واحسب نهايتها.')
+SOL()+Q(r'$v_{n+1}=0{,}5d_n+2-4=0{,}5(d_n-4)=\RR{0{,}5\,v_n}$ ؛ $v_0=\RR{-2}$.',r'$d_n=\RR{4-2\times0{,}5^n}$ ؛ \quad $'+LN+r'd_n=\RR{4}$ mg: الكمية تستقر عند $4$ mg.')
+HW(r'مسائل من باب المتتاليات.'),
[r'وضعية بيئية.',r'عمل بالأفواج.',r'تفسير النتائج.',r'نهاية المحور: فرض أو مراجعة.']))

